package com.cpf.starter.smb;import com.hierynomus.msdtyp.AccessMask;import com.hierynomus.msfscc.fileinformation.FileIdBothDirectoryInformation;import com.hierynomus.protocol.commons.EnumWithValue.EnumSet;import com.hierynomus.smbj.*;import com.hierynomus.smbj.auth.AuthenticationContext;import com.hierynomus.smbj.connection.Connection;import com.hierynomus.smbj.session.Session;import com.hierynomus.smbj.share.*;import java.io.*;import java.nio.file.*;import java.util.*;public final class CpfSmbClient {private final CpfSmbProperties p;public CpfSmbClient(CpfSmbProperties p){this.p=p;}public void upload(Path local,String remote)throws IOException{if(Files.size(local)>p.getMaxBytes())throw new IOException("SMB limit");with(share->{try(com.hierynomus.smbj.share.File f=share.openFile(safe(remote),EnumSet.of(AccessMask.GENERIC_WRITE),null,SMB2ShareAccess.ALL,SMB2CreateDisposition.FILE_OVERWRITE_IF,null);InputStream in=Files.newInputStream(local);OutputStream out=f.getOutputStream()){in.transferTo(out);}return null;});}public void download(String remote,Path local)throws IOException{with(share->{Files.createDirectories(local.toAbsolutePath().getParent());try(com.hierynomus.smbj.share.File f=share.openFile(safe(remote),EnumSet.of(AccessMask.GENERIC_READ),null,SMB2ShareAccess.ALL,SMB2CreateDisposition.FILE_OPEN,null);InputStream in=f.getInputStream();OutputStream out=Files.newOutputStream(local)){in.transferTo(out);}if(Files.size(local)>p.getMaxBytes())throw new IOException("SMB limit");return null;});}public List<String> list(String dir)throws IOException{return with(s->s.list(safe(dir)).stream().map(FileIdBothDirectoryInformation::getFileName).filter(n->!n.equals(".")&&!n.equals("..")).toList());}public void delete(String path)throws IOException{with(s->{s.rm(safe(path));return null;});}private String safe(String x){Path n=Path.of(x).normalize();if(n.isAbsolute()||n.startsWith(".."))throw new SecurityException("unsafe SMB path");return n.toString().replace('\\','/');}private <T>T with(Op<T> op)throws IOException{p.validate();try(SMBClient c=new SMBClient();Connection con=c.connect(p.getHost())){Session session=con.authenticate(new AuthenticationContext(p.getUsername(),p.getPassword().toCharArray(),p.getDomain()));try(DiskShare share=(DiskShare)session.connectShare(p.getShare())){return op.run(share);}}}private interface Op<T>{T run(DiskShare s)throws IOException;}}
